const sceneCode = String(params.scene_code || '').trim();
const sceneNameInput = String(params.scene_name || '').trim();
const quality = String(params.quality || 'm').toLowerCase().trim();
const format = String(params.format || 'mp4').toLowerCase().trim();
const customFilename = String(params.output_filename || '').trim();

if (!sceneCode) {
  return { error: 'Parameter "scene_code" is required to render a Manim animation.' };
}

// Write scene code to sandbox file
const tempSceneFile = `temp_scene_${Date.now()}_${Math.random().toString(36).slice(2, 6)}.py`;
try {
  fs.writeFile(tempSceneFile, sceneCode);
} catch (writeErr) {
  return { error: 'Failed to write temporary scene file: ' + writeErr.message };
}

const pyRunner = `
import ast, json, os, shutil, subprocess, sys, tempfile, time
from pathlib import Path

def run_manim_pipeline(input_scene_path, explicit_scene, quality_flag, fmt, out_filename):
    start_time = time.perf_counter()

    scene_path = Path(input_scene_path).resolve()
    if not scene_path.exists():
        return {"error": f"Scene file not found at {input_scene_path}"}

    code_str = scene_path.read_text(encoding="utf-8")

    # 1. Parse scene name from AST if not supplied
    target_scene = explicit_scene
    if not target_scene:
        try:
            tree = ast.parse(code_str)
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    for base in node.bases:
                        b_name = getattr(base, 'id', '') or getattr(base, 'attr', '')
                        if 'Scene' in b_name:
                            target_scene = node.name
                            break
                    if target_scene: break
        except Exception as e:
            return {"error": f"Syntax error in provided Python Scene code: {str(e)}"}

    if not target_scene:
        return {"error": "No Scene subclass detected. Define a class that inherits from Scene (e.g., class MyAnimation(Scene):)."}

    # 2. Check if Manim is installed; if not, auto-install into isolated .venv_manim
    cwd = Path.cwd()
    venv_dir = cwd / ".venv_manim"
    venv_py = venv_dir / ("Scripts/python.exe" if os.name == "nt" else "bin/python")

    python_exe = sys.executable
    # Check host manim
    has_manim = False
    try:
        r = subprocess.run([python_exe, "-c", "import manim; print('OK')"], capture_output=True, text=True)
        if r.returncode == 0: has_manim = True
    except Exception: pass

    if not has_manim:
        if venv_py.exists():
            python_exe = str(venv_py)
            has_manim = True
        else:
            subprocess.run([sys.executable, "-m", "venv", str(venv_dir)], capture_output=True, check=True)
            subprocess.run([str(venv_py), "-m", "pip", "install", "--no-cache-dir", "manim", "imageio-ffmpeg"], capture_output=True, check=True)
            python_exe = str(venv_py)
            has_manim = True

    # 3. Locate FFmpeg binary (using imageio_ffmpeg if not in PATH)
    ffmpeg_exe = shutil.which("ffmpeg")
    if not ffmpeg_exe:
        try:
            r_ff = subprocess.run([python_exe, "-c", "import imageio_ffmpeg; print(imageio_ffmpeg.get_ffmpeg_exe())"], capture_output=True, text=True)
            if r_ff.returncode == 0 and os.path.isfile(r_ff.stdout.strip()):
                ffmpeg_exe = r_ff.stdout.strip()
        except Exception: pass

    # 4. Prepare isolated render sandbox
    with tempfile.TemporaryDirectory(prefix="aiplate_manim_") as tmp_dir:
        tmp_path = Path(tmp_dir)
        media_out_dir = tmp_path / "media"
        media_out_dir.mkdir(parents=True, exist_ok=True)

        env = os.environ.copy()
        if ffmpeg_exe:
            env["PATH"] = os.path.dirname(ffmpeg_exe) + os.pathsep + env.get("PATH", "")

        q_arg = f"-q{quality_flag}"
        cmd = [python_exe, "-m", "manim", "render", q_arg, "--media_dir", str(media_out_dir)]
        if fmt == "gif": cmd.append("-i")
        cmd.extend([str(scene_path), target_scene])

        render_res = subprocess.run(cmd, capture_output=True, text=True, env=env, cwd=str(tmp_path), timeout=600)
        if render_res.returncode != 0:
            err_msg = render_res.stderr.strip() or render_res.stdout.strip()
            return {"error": f"Manim rendering failed (exit {render_res.returncode})", "details": err_msg[-2000:]}

        # Locate output video/gif
        ext = ".gif" if fmt == "gif" else ".mp4"
        candidates = [p for p in media_out_dir.rglob(f"*{ext}") if "partial_movie_files" not in str(p)]
        if not candidates:
            return {"error": f"Render finished but no {ext} video was found.", "stdout": render_res.stdout[-1000:]}

        final_media = sorted(candidates, key=lambda p: p.stat().st_mtime, reverse=True)[0]

        # 5. Move deliverable into workspace artifacts/animations/
        artifacts_dir = cwd / "artifacts" / "animations"
        artifacts_dir.mkdir(parents=True, exist_ok=True)

        dest_filename = out_filename if out_filename else f"{target_scene}_{quality_flag}{ext}"
        if not dest_filename.endswith(ext): dest_filename += ext
        dest_path = artifacts_dir / dest_filename

        shutil.copy2(str(final_media), str(dest_path))

        elapsed = round(time.perf_counter() - start_time, 2)
        file_size_kb = round(dest_path.stat().st_size / 1024, 2)

        return {
            "status": "success",
            "scene_name": target_scene,
            "quality": quality_flag,
            "format": fmt,
            "output_path": str(dest_path),
            "filename": dest_filename,
            "relative_path": f"artifacts/animations/{dest_filename}",
            "file_size_kb": file_size_kb,
            "render_latency_sec": elapsed
        }

if __name__ == '__main__':
    in_file = sys.argv[1] if len(sys.argv) > 1 else ''
    scene = sys.argv[2] if len(sys.argv) > 2 else ''
    q = sys.argv[3] if len(sys.argv) > 3 else 'm'
    f = sys.argv[4] if len(sys.argv) > 4 else 'mp4'
    out_f = sys.argv[5] if len(sys.argv) > 5 else ''
    try:
        res = run_manim_pipeline(in_file, scene, q, f, out_f)
    finally:
        try:
            if in_file and os.path.exists(in_file):
                os.remove(in_file)
        except Exception: pass
    print('___MANIM_OUTPUT_START___' + json.dumps(res) + '___MANIM_OUTPUT_END___')
`;

let stdout = '';
try {
  const runRes = await shell.runPython(pyRunner, [
    tempSceneFile,
    sceneNameInput,
    quality,
    format,
    customFilename
  ], 600000);
  stdout = runRes.stdout;
} catch (err) {
  return { error: 'Failed to execute Manim render process: ' + (err.message || String(err)) };
}

let resData = null;
if (stdout.includes('___MANIM_OUTPUT_START___') && stdout.includes('___MANIM_OUTPUT_END___')) {
  try {
    const jsonStr = stdout.split('___MANIM_OUTPUT_START___')[1].split('___MANIM_OUTPUT_END___')[0];
    resData = JSON.parse(jsonStr);
  } catch (parseErr) {
    return { error: 'Failed to parse Manim render result: ' + parseErr.message, raw: stdout };
  }
} else {
  return { error: 'No structured output returned by Manim engine', raw: stdout };
}

if (resData.error) {
  return resData;
}

const qualityLabels = { l: '480p (Low)', m: '720p (Standard)', h: '1080p (High)', k: '4K (Ultra)' };

