            ${resData.scene_name}
            <span style="font-size: 10px; padding: 2px 7px; background: rgba(59, 130, 246, 0.2); color: #3b82f6; border-radius: 10px; font-weight: 700; text-transform: uppercase;">
              ${resData.format}
            </span>
          </div>
          <div style="font-size: 11px; color: var(--text-dim);">
            Manim Community Edition • ${qualityLabels[resData.quality] || resData.quality}
          </div>
        </div>
      </div>
      <div style="display: flex; align-items: center; gap: 8px;">
        <span style="font-size: 11px; color: var(--text-dim); background: rgba(0,0,0,0.25); padding: 3px 8px; border-radius: 6px;">
          ⏱️ ${resData.render_latency_sec}s
        </span>
        <span style="font-size: 11px; color: #10b981; background: rgba(16, 185, 129, 0.15); padding: 3px 8px; border-radius: 6px; font-weight: 600;">
          💾 ${resData.file_size_kb} KB
        </span>
      </div>
    </div>

    <div style="display: flex; align-items: center; justify-content: space-between; background: rgba(0,0,0,0.3); border-radius: 8px; padding: 10px 14px; font-size: 12px;">
      <span style="color: var(--text-dim);">Deliverable File:</span>
      <span style="color: var(--text-accent); font-family: monospace; font-weight: 600;">📁 ${resData.relative_path}</span>
    </div>

    <div style="font-size: 11.5px; color: var(--text-dim); line-height: 1.5;">
      ✅ Video successfully compiled without residual partial frame caches in workspace root.
    </div>
  </div>
`;

return {
  ui_type: 'card',
  html: cardHtml,
  ...resData
};

const action = String(params.action || 'check').trim().toLowerCase();

const pyCode = `
import json, os, shutil, subprocess, sys
from pathlib import Path

act = sys.argv[1] if len(sys.argv) > 1 else 'check'
cwd = Path.cwd()
venv_dir = cwd / ".venv_manim"
venv_py = venv_dir / ("Scripts/python.exe" if os.name == "nt" else "bin/python")

if act == 'purge_cache':
    removed = []
    for p in [cwd / ".manim_cache", cwd / "media"]:
        if p.exists():
            shutil.rmtree(str(p), ignore_errors=True)
            removed.append(str(p))
    print(json.dumps({"status": "purged", "removed": removed}))
    sys.exit(0)

# Test manim
has_manim = False
manim_ver = "unknown"
try:
    r = subprocess.run([sys.executable, "-c", "import manim; print(manim.__version__)"], capture_output=True, text=True)
    if r.returncode == 0:
        has_manim = True
        manim_ver = r.stdout.strip()
except Exception: pass

is_venv = False
if not has_manim and venv_py.exists():
    try:
        r = subprocess.run([str(venv_py), "-c", "import manim; print(manim.__version__)"], capture_output=True, text=True)
        if r.returncode == 0:
            has_manim = True
            manim_ver = r.stdout.strip()
            is_venv = True
    except Exception: pass

if act == 'install_isolated' and not has_manim:
    subprocess.run([sys.executable, "-m", "venv", str(venv_dir)], capture_output=True, check=True)
    subprocess.run([str(venv_py), "-m", "pip", "install", "--no-cache-dir", "manim", "imageio-ffmpeg"], capture_output=True, check=True)
    has_manim = True
    is_venv = True
    manim_ver = "installed (latest)"

# Test ffmpeg
ffmpeg_path = shutil.which("ffmpeg")
if not ffmpeg_path:
    try:
        r_ff = subprocess.run([sys.executable, "-c", "import imageio_ffmpeg; print(imageio_ffmpeg.get_ffmpeg_exe())"], capture_output=True, text=True)
        if r_ff.returncode == 0 and os.path.isfile(r_ff.stdout.strip()):
            ffmpeg_path = r_ff.stdout.strip()
    except Exception: pass

print(json.dumps({
    "has_manim": has_manim,
    "manim_version": manim_ver,
    "is_venv": is_venv,
    "has_ffmpeg": bool(ffmpeg_path),
    "ffmpeg_path": ffmpeg_path,
    "python": sys.executable
}))
`;

let stdout = '';
try {
  const res = await shell.runPython(pyCode, [action], 120000);
  stdout = res.stdout;
} catch (err) {
  return { error: 'Failed to inspect environment: ' + (err.message || String(err)) };
}

let info = {};
try {
  info = JSON.parse(stdout.trim());
} catch (e) {
  return { error: 'Invalid output: ' + stdout };
}

const ready = info.has_manim && info.has_ffmpeg;
const statusColor = ready ? '#10b981' : '#f59e0b';
const statusText = ready ? `Ready (Manim v${info.manim_version})` : 'Setup Needed';

const cardHtml = `
  <div class="plugin-custom-card" style="border: 1px solid ${statusColor}; padding: 14px 16px; border-radius: 10px; gap: 10px;">
    <div style="display: flex; align-items: center; justify-content: space-between;">
      <div style="font-weight: 700; font-size: 13px; color: var(--text-main); display: flex; align-items: center; gap: 6px;">
        ⚙️ Manim Studio Runtime Environment
      </div>
      <span style="font-size: 11px; padding: 2px 8px; border-radius: 12px; background: rgba(0,0,0,0.3); color: ${statusColor}; font-weight: 600;">
        ${statusText}
      </span>
    </div>
    <div style="font-size: 11.5px; color: var(--text-dim); line-height: 1.5;">
      Manim Community: <strong>${info.has_manim ? 'Available' : 'Not Found'}</strong> (v${info.manim_version})<br>
      FFmpeg Video Codec: <strong>${info.has_ffmpeg ? 'Available' : 'Missing'}</strong> (${info.ffmpeg_path || 'None'})
    </div>
  </div>
`;

return {
  ui_type: 'card',
  html: cardHtml,
  ...info
};

