import os, sys, shutil
from pathlib import Path

cwd = Path.cwd()
targets = [
    cwd / ".venv_manim",
    cwd / ".manim_cache",
    cwd / "media",
    cwd / ".agents" / "skills" / "manim" / ".venv_manim",
    cwd / "plugins" / "installed" / "manim_studio" / ".venv_manim"
]
for t in targets:
    if t.exists():
        if t.is_dir(): shutil.rmtree(str(t), ignore_errors=True)
        else: t.unlink(missing_ok=True)
`;
